class FakeTransitionEvent extends Event {
  propertyName: string;
  elapsedTime: number;
  pseudoElement: string;

  constructor(type: string, init: Partial<TransitionEventInit & { pseudoElement?: string }> = {}) {
    super(type, { bubbles: true, cancelable: false });
    this.propertyName = init.propertyName || '';
    this.elapsedTime = init.elapsedTime ?? 0.0;
    this.pseudoElement = init.pseudoElement || '';
  }
}

// Подменяем глобально
vi.stubGlobal('TransitionEvent', FakeTransitionEvent);

// happy-dom не полностью реализует ARIA IDL-отражение (`ARIAMixin`): свойства
// вида `element.ariaDisabled` не синхронизированы с одноимёнными атрибутами
// `aria-disabled`, а `element.role` без атрибута возвращает `''` вместо `null`.
// jsdom это поддерживает, и тесты полагаются на `el.ariaDisabled === 'true'`
// и `el.role === null`. Восстанавливаем поведение через геттеры/сеттеры.
const ARIA_PROPS: ReadonlyArray<readonly [string, string]> = [
  ['ariaAtomic', 'aria-atomic'],
  ['ariaAutoComplete', 'aria-autocomplete'],
  ['ariaBrailleLabel', 'aria-braillelabel'],
  ['ariaBrailleRoleDescription', 'aria-brailleroledescription'],
  ['ariaBusy', 'aria-busy'],
  ['ariaChecked', 'aria-checked'],
  ['ariaColCount', 'aria-colcount'],
  ['ariaColIndex', 'aria-colindex'],
  ['ariaColSpan', 'aria-colspan'],
  ['ariaCurrent', 'aria-current'],
  ['ariaDescription', 'aria-description'],
  ['ariaDisabled', 'aria-disabled'],
  ['ariaExpanded', 'aria-expanded'],
  ['ariaHasPopup', 'aria-haspopup'],
  ['ariaHidden', 'aria-hidden'],
  ['ariaInvalid', 'aria-invalid'],
  ['ariaKeyShortcuts', 'aria-keyshortcuts'],
  ['ariaLabel', 'aria-label'],
  ['ariaLevel', 'aria-level'],
  ['ariaLive', 'aria-live'],
  ['ariaModal', 'aria-modal'],
  ['ariaMultiLine', 'aria-multiline'],
  ['ariaMultiSelectable', 'aria-multiselectable'],
  ['ariaOrientation', 'aria-orientation'],
  ['ariaPlaceholder', 'aria-placeholder'],
  ['ariaPosInSet', 'aria-posinset'],
  ['ariaPressed', 'aria-pressed'],
  ['ariaReadOnly', 'aria-readonly'],
  ['ariaRelevant', 'aria-relevant'],
  ['ariaRequired', 'aria-required'],
  ['ariaRoleDescription', 'aria-roledescription'],
  ['ariaRowCount', 'aria-rowcount'],
  ['ariaRowIndex', 'aria-rowindex'],
  ['ariaRowSpan', 'aria-rowspan'],
  ['ariaSelected', 'aria-selected'],
  ['ariaSetSize', 'aria-setsize'],
  ['ariaSort', 'aria-sort'],
  ['ariaValueMax', 'aria-valuemax'],
  ['ariaValueMin', 'aria-valuemin'],
  ['ariaValueNow', 'aria-valuenow'],
  ['ariaValueText', 'aria-valuetext'],
] as const;

const defineReflectedAttr = (proto: object, idlName: string, attrName: string): void => {
  Object.defineProperty(proto, idlName, {
    configurable: true,
    enumerable: true,
    get(this: Element): string | null {
      return this.getAttribute(attrName);
    },
    set(this: Element, value: string | null): void {
      if (value === null) {
        this.removeAttribute(attrName);
      } else {
        this.setAttribute(attrName, value);
      }
    },
  });
};

for (const [idlName, attrName] of ARIA_PROPS) {
  defineReflectedAttr(Element.prototype, idlName, attrName);
}
// `role` отражается как `element.role` (null при отсутствии атрибута).
defineReflectedAttr(Element.prototype, 'role', 'role');

// happy-dom `HTMLFormElement.reset()` восстанавливает `defaultValue` для `<input>`,
// но не возвращает `<select>` к option'у с `defaultSelected`. jsdom это делает.
// Восстанавливаем вручную после нативного `reset`.
// eslint-disable-next-line @typescript-eslint/unbound-method
const _origFormReset = HTMLFormElement.prototype.reset;
HTMLFormElement.prototype.reset = function (this: HTMLFormElement): void {
  _origFormReset.call(this);
  // eslint-disable-next-line no-restricted-properties
  for (const sel of Array.from(this.querySelectorAll('select'))) {
    const defaultOption = Array.from(sel.options).find((opt) => opt.defaultSelected);
    if (defaultOption) {
      sel.value = defaultOption.value;
    } else if (sel.options.length > 0) {
      sel.selectedIndex = 0;
    }
  }
};

// happy-dom 20 помечает `HTMLImageElement.complete = true` сразу после рендера
// `<img src>` (без реальной загрузки), из-за чего `ImageBase` считает картинку
// уже загруженной и диспатчит `load` автоматически. jsdom и happy-dom 18
// возвращали `false` для незагруженной картинки. Возвращаем `false` по умолчанию
// (тесты, которым нужно `complete=true`, мокают его через `defineProperty`).
Object.defineProperty(HTMLImageElement.prototype, 'complete', {
  configurable: true,
  get(this: HTMLImageElement): boolean {
    return false;
  },
});

// Замена vitest.global-setup.ts
vi.stubEnv('TZ', 'UTC');

import { act } from 'react';
import { fireEvent, render, screen } from '@testing-library/react';
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { baselineComponent } from '../../testing/utils';
import { ActionSheetContext } from '../ActionSheet/ActionSheetContext';
import { ActionSheetItem, type ActionSheetItemProps } from './ActionSheetItem';

const ActionSheetItemTest = (props: ActionSheetItemProps) => (
  <ActionSheetItem data-testid="item" {...props} />
);
const item = () => screen.getByTestId('item');

describe('ActionSheetItem', () => {
  baselineComponent((props) => <ActionSheetItem {...props}>ActionSheetItem</ActionSheetItem>);

  describe('deprecation warnings', () => {
    let warnSpy: ReturnType<typeof vi.spyOn>;

    beforeEach(() => {
      vi.stubEnv('NODE_ENV', 'development');
      warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => void 0);
    });

    afterEach(() => {
      warnSpy.mockClear();
      vi.unstubAllEnvs();
    });

    afterAll(() => {
      warnSpy.mockRestore();
    });

    it('warns when mode="cancel" is used', () => {
      render(<ActionSheetItemTest mode="cancel">Cancel</ActionSheetItemTest>);
      expect(warnSpy).toHaveBeenCalledTimes(1);
      const callArgs = warnSpy.mock.calls[0];
      expect(callArgs[0]).toContain('mode="cancel"');
    });

    it('warns when isCancelItem is used', () => {
      render(<ActionSheetItemTest isCancelItem>Cancel</ActionSheetItemTest>);
      expect(warnSpy).toHaveBeenCalledTimes(1);
      const callArgs = warnSpy.mock.calls[0];
      expect(callArgs[0]).toContain('isCancelItem');
    });

    it('does not warn when neither mode="cancel" nor isCancelItem is used', () => {
      render(<ActionSheetItemTest>Item</ActionSheetItemTest>);
      expect(warnSpy).not.toHaveBeenCalled();
    });
  });

  describe('cancel item detection', () => {
    const onItemClickCallback = vi.fn();

    beforeEach(() => {
      onItemClickCallback.mockClear();
    });

    const renderWithContext = (props: ActionSheetItemProps) => {
      return render(
        <ActionSheetContext.Provider
          value={{
            onItemClick: onItemClickCallback,
          }}
        >
          <ActionSheetItemTest data-testid="cancel-item" {...props}>
            Cancel
          </ActionSheetItemTest>
        </ActionSheetContext.Provider>,
      );
    };

    const clickCancelItem = async () => {
      await act(async () =>
        fireEvent(
          screen.getByTestId('cancel-item'),
          new MouseEvent('click', {
            clientX: 1,
            clientY: 1,
            bubbles: true,
          }),
        ),
      );
    };

    const expectCancelItemDetected = () => {
      expect(onItemClickCallback).toHaveBeenCalledTimes(1);
      const callArgs = onItemClickCallback.mock.calls[0][0];
      expect(callArgs.isCancelItem).toBe(true);
    };

    it('detects cancel item via isCancelItem prop (backward compatibility)', async () => {
      renderWithContext({ isCancelItem: true });
      await clickCancelItem();
      expectCancelItemDetected();
    });
  });

  it('Component: ActionSheetItem is a custom button by default', () => {
    render(<ActionSheetItemTest>ActionSheetItem</ActionSheetItemTest>);
    expect(item().tagName.toLowerCase()).toMatch('div');
    expect(item()).toHaveAttribute('role', 'button');
    expect(item()).toHaveAttribute('tabindex', '0');
  });

  it('Component: ActionSheetItem w/ href is a native link', () => {
    render(<ActionSheetItemTest href="https://vk.ru">ActionSheetItem</ActionSheetItemTest>);
    const el = item();
    expect(el.tagName.toLowerCase()).toMatch('a');
  });

  it('Component: ActionSheetItem[selectable] is a label', () => {
    render(<ActionSheetItemTest selectable>ActionSheetItem</ActionSheetItemTest>);
    expect(item().tagName.toLowerCase()).toMatch('label');
  });

  it('should call close callback when Enter keydown', async () => {
    const onCloseCallback = vi.fn();
    render(
      <ActionSheetContext.Provider
        value={{
          onClose: onCloseCallback,
        }}
      >
        <ActionSheetItemTest selectable data-testid="action-item">
          ActionSheetItem
        </ActionSheetItemTest>
      </ActionSheetContext.Provider>,
    );

    await act(async () =>
